// アバターと同じ姿勢を、この拡張機能の設定で調整してゲームへ渡す。
(() => {
  const KEYS = ["x", "y", "z", "yaw", "pitch", "roll"];
  const mapPose = (value) => Object.fromEntries(KEYS.map((key) => [key, value(key)]));
  const ZERO = mapPose(() => 0);
  const defaults = lfx.manifest.defaults;
  const now = () => performance.now();
  let settings = lfx.settings, latest = null, center = ZERO;
  let lastFaceAt = -Infinity, lastSentAt = -Infinity, faceLost = false;
  let filtered = ZERO, previous = ZERO, velocity = ZERO, output = ZERO, held = ZERO, lastPose = ZERO;
  let dirty = false, sending = false, error = "", game = "";
  const sent = [];

  const face = () => !faceLost && !!latest && now() - lastFaceAt < 500;
  const pruneSent = (at) => { while (sent.length && sent[0] <= at - 1000) sent.shift(); };
  const position = (key) => key.length === 1;
  const option = (key, min, max) => Number.isFinite(settings[key]) ?
    Math.max(min, Math.min(max, settings[key])) : defaults[key];

  function adjust(pose) {
    return mapPose((key) => {
      const dead = position(key) ? option("positionDeadzone", 0, 3) : option("angleDeadzone", 0, 5);
      const amount = Math.max(0, Math.abs(pose[key]) - dead) * option(key + "Gain", 0, 3);
      return amount ? amount * Math.sign(pose[key]) * (settings[key + "Invert"] === true ? -1 : 1) : 0;
    });
  }

  function filter(pose, dt) {
    const strength = option("smoothing", 0, 1);
    if (!strength || !dt) {
      velocity = ZERO;
      return pose;
    }
    const blend = (before, next, hz) => {
      const step = 2 * Math.PI * hz * dt;
      return before + (next - before) * step / (1 + step);
    };
    // 動きが速いほど新しい値を多く使い、静かなときは小さなぶれを抑える。
    velocity = mapPose((key) => blend(velocity[key], (pose[key] - previous[key]) / dt, 1));
    return mapPose((key) => {
      const speed = Math.abs(velocity[key]) * (position(key) ? 4 : 1);
      const cutoff = 1 / strength + 0.4 * speed;
      return blend(filtered[key], pose[key], cutoff);
    });
  }

  async function send(pose, at) {
    sending = true;
    lastSentAt = at;
    lastPose = pose;
    let result;
    try { result = await lfx.trackirSend(pose); }
    catch { result = { ok: false, error: "TrackIR に渡せません" }; }
    sending = false;
    error = result.ok ? "" : result.error;
    game = result.game || "";
    if (result.ok) sent.push(now());
  }

  lfx.onSettings((next) => {
    settings = next;
    if (face()) { output = adjust(filtered); dirty = true; }
  });
  lfx.onPose((pose) => {
    if (!pose.face) { faceLost = true; return; }
    const at = now();
    const relative = mapPose((key) => pose[key] - center[key]);
    filtered = filter(relative, face() ? (at - lastFaceAt) / 1000 : 0);
    previous = relative;
    latest = pose;
    lastFaceAt = at;
    faceLost = false;
    output = adjust(filtered);
    dirty = true;
  });
  lfx.onCommand((id) => {
    if (id !== "center") return;
    if (!face()) return { ok: false, error: "顔が見えていません" };
    center = { ...latest };
    filtered = previous = velocity = output = ZERO;
    dirty = true;
    return { ok: true };
  });

  setInterval(() => {
    if (sending) return;
    const at = now(), age = at - lastFaceAt;
    if (age < 500) {
      if (!dirty || faceLost) return;
      dirty = false;
      held = output;
      return send(output, at);
    }
    if (age < 1100) {
      // 最後に渡した姿勢を 0.5 秒保ち、0.6 秒かけて正面に戻す。
      const t = (age - 500) / 600;
      const keep = 1 - t * t * (3 - 2 * t);
      return send(mapPose((key) => held[key] * keep), at);
    }
    // 顔を待っている間にも新しく開いたゲームを見つけられるようにする。
    if (lastPose !== ZERO || at - lastSentAt >= 100) return send(ZERO, at);
  }, 1000 / 60);

  function publish() {
    pruneSent(now());
    const [level, text] = error ? [error === "Windows だけで使えます" ? "warn" : "err", error] :
      !face() ? ["warn", "顔が見えません"] :
      sent.length ? ["ok", `${game ? game + " に渡しています" : "送っています"}（${sent.length} 回/秒）`] :
        ["warn", "送る準備中…"];
    const values = mapPose((key) => Math.round(lastPose[key] * 10) / 10);
    lfx.status({ level, text, values });
  }
  publish();
  setInterval(publish, 110);
})();
